   "titleVi": "Vs 得不得了 / Vs 極了 — cực kỳ",
   "giaiThich": "Nhấn mạnh mức độ rất cao. Bổ ngữ 得不得了 đứng sau tính từ. Đã dùng mẫu này thì KHÔNG thêm 很, 非常 phía trước nữa."
