   "titleVi": "讓 — để cho, nhường (lịch sự)",
   "giaiThich": "讓 làm động từ với nhiều nghĩa: \"khiến cho\" và \"để cho, nhường\" (ví dụ 讓美心請客吧 — để Mỹ Tâm mời nhé)."
